import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.C83Ss68L.js";const p=JSON.parse('{"title":"ADR-0004: Hexagonal layout with a pure core","description":"Four layers — shared types, pure core services, infrastructure with I/O, framework adapters — with two documented pragmatic exceptions.","frontmatter":{"title":"ADR-0004: Hexagonal layout with a pure core","description":"Four layers — shared types, pure core services, infrastructure with I/O, framework adapters — with two documented pragmatic exceptions."},"headers":[],"relativePath":"explanation/decisions/adr-0004-hexagonal-core.md","filePath":"explanation/decisions/adr-0004-hexagonal-core.md","lastUpdated":1791568280000}'),i={name:"explanation/decisions/adr-0004-hexagonal-core.md"};function n(s,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0004-hexagonal-layout-with-a-pure-core" tabindex="-1">ADR-0004: Hexagonal layout with a pure core <a class="header-anchor" href="#adr-0004-hexagonal-layout-with-a-pure-core" aria-label="Permalink to &quot;ADR-0004: Hexagonal layout with a pure core&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-09-03 (released in v2.0.0)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The toolkit runs in browsers, Node, Bun, workers and SSR build steps. When domain logic touches <code>window</code>, <code>fetch</code> or the filesystem directly, two things break at once: unit tests need environment stubs to test pure logic, and any server-side import risks touching a browser API. Early versions had services with mixed responsibilities and no rule about where I/O was allowed.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Four layers with one direction of dependency, described in full on the <a href="/katanakit-js/guides/architecture">Architecture</a> page:</p><ol><li><code>types/</code> — the shared kernel: every contract and domain type, single source of truth.</li><li><code>core/services/</code> — pure logic. No <code>window</code>, <code>document</code>, <code>fetch</code>, filesystem or framework.</li><li><code>infrastructure/</code> — the I/O owners (DOM, storage, viewport, sensors, observer, worker, theme, decorators), each guarded or with an SSR fallback.</li><li><code>adapters/</code> — framework entry points, published on subpaths (<a href="/katanakit-js/explanation/decisions/adr-0003-adapter-subpath-exports">ADR-0003</a>).</li></ol><p>Plus <code>config/</code> (site + SEO) and an optional <code>prisma/</code> layer. Two pragmatic exceptions are documented in code rather than hidden: <code>http.service.ts</code> wraps the global <code>fetch</code> (present in every supported runtime), and <code>reactive.service.ts</code> persists through injected storage functions instead of importing infrastructure. <code>db.ts</code> is the only module that reads the environment, and it is not part of the public barrel.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> Core logic is testable without mocks; SSR safety is structural because guards live at the edge; swapping implementations goes through strategies rather than edits. A reviewer can tell where a change belongs from one question: does it do I/O?</p><p><strong>Worse.</strong> More files and indirection for small helpers. The boundary is enforced by review discipline, not the compiler — a stray <code>window</code> reference in <code>core/</code> would pass <code>tsc</code>. And the exceptions are load-bearing: if they stop being documented, they will eventually be read as violations and &quot;fixed&quot;.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/katanakit-js/guides/architecture">Architecture</a> — layer by layer, with the pattern table.</li><li><a href="https://github.com/senseikatana/katanakit-js/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributing contract</a> — rules 1, 10 and 11.</li></ul>',13)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
